        public static string WordOfTheDay
        {
            get
            {
                DateTime loopStart = new(2026, 8, 11);
                DateTime now = DateTime.Today;

                TimeSpan elapsed = now.Subtract(loopStart);

                int index = elapsed.Days % WordDefinitions.Count;

                return new List<string>(WordDefinitions.Keys)[index];
            }
        }
